// n8n Code node (JavaScript)
const inputs = $input.all();

return inputs.map(entry => {
  // Capturamos el contenido bruto del nodo anterior
  let rawContent = entry.json.output || "";

  // Normalización: forzar que el contenido sea tratado como cadena de texto
  if (typeof rawContent !== "string") {
    rawContent = JSON.stringify(rawContent);
  }

  let finalString = rawContent;

  // Localizar bloques de código markdown (```json o ```)
  const codeBlockRegex = /```(?:json)?\s*([\s\S]*?)```/;
  const matchBlock = rawContent.match(codeBlockRegex);

  if (matchBlock && matchBlock[1]) {
    finalString = matchBlock[1].trim();
  }

  // Intentar la conversión a objeto
  let parsedResult = {};
  try {
    parsedResult = JSON.parse(finalString);
  } catch (err) {
    // Si falla, buscamos la estructura de llaves { ... } más externa
    const curlyBracesRegex = /\{[\s\S]+\}/;
    const fallbackMatch = finalString.match(curlyBracesRegex);
    if (fallbackMatch) {
      try {
        parsedResult = JSON.parse(fallbackMatch[0]);
      } catch (parseError) {
        // Si sigue fallando, parsedResult queda vacío
      }
    }
  }

  // Combinación y mapeo de campos al esquema final
  return {
    json: {
      ...entry.json,
      contratante_nombre: parsedResult.contratante_nombre ?? null,
      contratante_id: parsedResult.contratante_id ?? null,
      contratista_nombre: parsedResult.contratista_nombre ?? null,
      contratista_id: parsedResult.contratista_id ?? null,
      servicio_descripcion: parsedResult.servicio_descripcion ?? null,
      plazo_inicio: parsedResult.plazo_inicio ?? null,
      plazo_fin: parsedResult.plazo_fin ?? null,
      duracion_meses: parsedResult.duracion_meses ?? null,
      duracion_dias: parsedResult.duracion_dias ?? null,
      precio_monto: parsedResult.precio_monto ?? null,
      precio_moneda: parsedResult.precio_moneda ?? null,
      ciudad: parsedResult.ciudad ?? null,
      pais: parsedResult.pais ?? null,
      texto_usuario: entry.json.texto_usuario ?? null,
    }
  };
});

const item = $input.first();
// Cambiamos el fileName de la propiedad binaria 'data'
item.binary.data.fileName = 'audio.ogg';
item.binary.data.fileExtension = 'ogg';
item.binary.data.mimeType = 'audio/ogg';
return item;

// Captura de datos iniciales
const inputData = items[0]?.json || {};

/**
 * Normaliza valores para asegurar que sean números válidos
 * Maneja separadores de miles y decimales
 */
const parseNumeric = (value) => {
  if (value == null) return null;
  if (typeof value === 'number') return value;

  // Limpieza de formato: quita puntos de miles y estandariza coma decimal
  const sanitized = String(value)
    .replace(/[.,](?=\d{3}(?:\D|$))/g, '') 
    .replace(',', '.');

  const result = parseFloat(sanitized);
  return Number.isFinite(result) ? result : null;
};

// Mapeo estructurado de la información
const info = {
  contratante_nombre: inputData.contratante_nombre ?? null,
  contratante_id: inputData.contratante_id ?? null,
  contratista_nombre: inputData.contratista_nombre ?? null,
  contratista_id: inputData.contratista_id ?? null,
  servicio_descripcion: inputData.servicio_descripcion ?? null,
  plazo_inicio: inputData.plazo_inicio ?? null,
  plazo_fin: inputData.plazo_fin ?? null,
  duracion_meses: inputData.duracion_meses ?? null,
  duracion_dias: inputData.duracion_dias ?? null,
  precio_monto: parseNumeric(inputData.precio_monto),
  precio_moneda: inputData.precio_moneda ?? null,
  ciudad: inputData.ciudad ?? null,
  pais: inputData.pais ?? null
};

// Auditoría de campos requeridos
const camposRequeridos = [
  'contratante_nombre', 'contratante_id',
  'contratista_nombre', 'contratista_id',
  'servicio_descripcion', 'precio_monto', 'precio_moneda', 'pais'
];

const errores = [];

// Validación de integridad
camposRequeridos.forEach(campo => {
  const valor = info[campo];

  if (campo === 'precio_monto') {
    if (typeof valor !== 'number' || !Number.isFinite(valor)) {
      errores.push(campo);
    }
  } else if (!valor || (typeof valor === 'string' && !valor.trim())) {
    errores.push(campo);
  }
});

// Verificación lógica de temporalidad (Fin o Duración)
const poseeFechaFin = info.plazo_fin && String(info.plazo_fin).trim().length > 0;
const poseeDuracion = (Number(info.duracion_meses) > 0) || (Number(info.duracion_dias) > 0);

if (!poseeFechaFin && !poseeDuracion) {
  errores.push('plazo_fin (o duracion)');
}

// Salida compatible con el esquema original
return [{
  json: {
    ok: errores.length === 0,
    faltantes: errores,
    datos: info
  }
}];

const data = items[0].json;
const faltantes = data.faltantes || [];

const nombres = {
  contratante_nombre: '👤 Nombre del contratante',
  contratante_id: '🆔 ID/CUIT del contratante',
  contratista_nombre: '👤 Nombre del contratista',
  contratista_id: '🆔 ID/CUIT del contratista',
  servicio_descripcion: '📋 Descripción del servicio',
  precio_monto: '💰 Monto del precio',
  precio_moneda: '💱 Moneda',
  pais: '🌍 País',
  'plazo_fin (o duracion)': '📅 Fecha de fin o duración del contrato'
};

const lista = faltantes.map(f => nombres[f] || f).join('\n');

const mensaje = `⚠️ *Datos incompletos para generar el contrato*\n\nPor favor, enviá otro audio incluyendo la siguiente información que falta:\n\n${lista}\n\n🎙️ _Grabá un nuevo audio con todos los datos y lo vuelvo a procesar._`;

return [{ json: { mensaje } }];

// Obtener la fuente de datos (priorizando el nodo previo o el objeto anidado)
const source = items[0].json.datos || items[0].json;

/**
 * Formatea un objeto Date a string YYYY-MM-DD
 */
const toIsoDate = (dateObj) => dateObj.toISOString().split('T')[0];

/**
 * Lógica para desplazar fechas conservando integridad de días
 */
const shiftDate = (baseDate, m, d) => {
  const result = new Date(baseDate.getTime());

  if (m > 0) {
    const targetMonth = result.getMonth() + m;
    result.setMonth(targetMonth);
    // Ajuste de desbordamiento (ej: 31 de enero + 1 mes -> 28 de febrero)
    if (result.getMonth() > (targetMonth % 12)) result.setDate(0);
  }

  if (d > 0) result.setDate(result.getDate() + d);

  return result;
};

// Inicialización de puntos temporales
const dateStart = source.plazo_inicio ? new Date(source.plazo_inicio) : new Date();
let dateEnd = source.plazo_fin ? new Date(source.plazo_fin) : null;

const countMonths = parseInt(source.duracion_meses || 0);
const countDays = parseInt(source.duracion_dias || 0);

// Cálculo proyectado si la fecha de finalización está ausente
if (!dateEnd && (countMonths > 0 || countDays > 0)) {
  dateEnd = shiftDate(dateStart, countMonths, countDays);
}

// Generación de descripción textual de la vigencia
let labelDuration = "";
if (countMonths > 0) {
  labelDuration = `${countMonths} meses`;
} else if (countDays > 0) {
  labelDuration = `${countDays} días`;
}

return [{
  json: {
    ...source,
    plazo_inicio: toIsoDate(dateStart),
    plazo_fin: toIsoDate(dateEnd || dateStart),
    duracion_texto: labelDuration
  }
}];

