// Obtención de las regulaciones desde el nodo anterior
let regulaciones = $json.normativas;

// Si vino como texto, lo convertimos a array
if (typeof regulaciones === 'string') {
  regulaciones = JSON.parse(regulaciones);
}

// Construcción del bloque de texto para la base legal
const bloqueNormativo = regulaciones.map((reg) => {
  return `• *${reg.law_name}* — ${reg.topic.toUpperCase()}: ${reg.summary}\n🔗 [Referencia Legal](${reg.sources[0]})`;
}).join("\n\n");

// Redacción de la sección de validez digital según leyes argentinas
const textoFirmaArgentina = `✍️ *Validez de la Firma Digital y Electrónica*\n\nConforme a lo establecido en la *Ley 25.506 de Firma Digital* de la República Argentina, las partes declaran que el presente documento firmado mediante medios electrónicos goza de plena eficacia jurídica, integridad y autoría. El consentimiento expresado digitalmente es equivalente a la firma manuscrita según los términos de la normativa vigente.`;

return [
  {
    json: {
      ...$json,
      clausula_legal: `📘 *Marco Jurídico de Referencia*\n\n${bloqueNormativo}`,
      clausula_firma: textoFirmaArgentina,
    }
  }
];
